  "Could not read the settings: {error}": "No se pudieron leer los ajustes: {error}",
  "Editing the 64-bit helper this 32-bit game uses.": "Editando el asistente de 64 bits que usa este juego de 32 bits.",
  "Game is running. Changes land within a second.": "El juego está en ejecución. Los cambios llegan en un segundo.",
  "Game is not running. Changes apply when it starts.": "El juego no está en ejecución. Los cambios se aplican al iniciarlo.",
  "{name} (running)": "{name} (en ejecución)",
  "Everything back to default. A running game picks it up within a second.": "Todo de vuelta a los valores predeterminados. Un juego en ejecución lo aplica en un segundo.",
  "Default ({state})": "Predeterminado ({state})",
  "on": "activado",
  "off": "desactivado",
  "On": "Activado",
